```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::wasi::clocks::wall_clock;

struct Node;

const NOTIFY_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let seconds = wall_clock::now().seconds;

        // A transport failure is a value, not a trap: count it as zero characters.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let message = format!("heartbeat: {fetched} chars from {feed_url} at {seconds}");

        // `notified` is only ever reported as true. If the channel refuses every
        // attempt, the run traps rather than emitting a report that violates
        // `ensures notified == true`.
        let mut accepted = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                accepted = true;
                break;
            }
        }
        if !accepted {
            panic!("notifier refused the digest after {NOTIFY_ATTEMPTS} attempts");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified: true,
        }
    }
}

export!(Node);
```

